class CookieStore(typing.MutableMapping[str, str]):
    """A deterministic cookie store with explicit domain and path matching."""

    def __init__(self, cookies: CookieTypes | None = None, *, max_cookies: int | None = None, max_cookies_per_domain: int | None = None) -> None:
        for limit in (max_cookies, max_cookies_per_domain):
            if limit is not None and not isinstance(limit, int):
                raise TypeError("Cookie limits must be integers or None")
            if limit is not None and limit < 0:
                raise ValueError("Cookie limits must be non-negative")
        self.max_cookies = max_cookies
        self.max_cookies_per_domain = max_cookies_per_domain
        # Insertion order is creation order, including after replacement.
        self._store: dict[tuple[str, str, str], tuple[str, bool, bool, float | None]] = {}
        self.update(cookies)

    def _expire(self) -> None:
        now = time.time()
        for key, (_, _, _, expires) in list(self._store.items()):
            if expires is not None and expires <= now:
                del self._store[key]

    def _put(self, name: str, value: str, domain: str, path: str, host_only: bool, secure: bool, expires: float | None) -> None:
        self._expire()
        key = (name, domain, path)
        self._store.pop(key, None)
        if expires is not None and expires <= time.time():
            return
        self._store[key] = (value, host_only, secure, expires)
        if self.max_cookies_per_domain is not None:
            keys = [k for k in self._store if k[1] == domain]
            for old in keys[:max(0, len(keys) - self.max_cookies_per_domain)]:
                del self._store[old]
        if self.max_cookies is not None:
            for old in list(self._store)[:max(0, len(self._store) - self.max_cookies)]:
                del self._store[old]

    @staticmethod
    def _domain_matches(host: str, domain: str) -> bool:
        return host == domain or host.endswith("." + domain)

    def extract_cookies(self, response: Response) -> None:
        host = response.request.url.host.lower()
        request_path = response.request.url.path or "/"
        default_path = request_path.rsplit("/", 1)[0] or "/" if request_path.startswith("/") else "/"
        for header in response.headers.get_list("set-cookie"):
            # A comma followed by a cookie-pair starts a new cookie, not an Expires date.
            for item in re.split(r",(?=\\s*[^\\s;,=]+\\s*=)", header):
                parts = item.split(";")
                name, sep, value = parts[0].strip().partition("=")
                name = name.strip()
                value = value.strip()
                if not sep or not re.fullmatch(r"[!#$%&'*+.^_`|~0-9A-Za-z-]+", name):
                    continue
                if any(ord(c) < 32 or ord(c) == 127 for c in value):
                    continue
                attrs: dict[str, str | None] = {}
                for part in parts[1:]:
                    attr, equal, val = part.strip().partition("=")
                    if attr:
                        attrs[attr.lower()] = val.strip() if equal else None
                if any(k in attrs and not attrs[k] for k in ("domain", "max-age", "expires")):
                    continue
                domain_attr = attrs.get("domain")
                domain = domain_attr.lower().lstrip(".") if domain_attr else host
                if not domain or domain.endswith(".") or not self._domain_matches(host, domain):
                    continue
                path_attr = attrs.get("path")
                path = path_attr if path_attr and path_attr.startswith("/") else default_path
                secure = "secure" in attrs
                https = response.request.url.scheme == "https"
                if name.startswith("__Secure-") and not (secure and https):
                    continue
                if name.startswith("__Host-") and not (secure and https and "domain" not in attrs and path_attr == "/"):
                    continue
                expires = None
                age = attrs.get("max-age")
                if age is not None and re.fullmatch(r"-?[0-9]+", age):
                    seconds = int(age)
                    expires = time.time() + seconds if seconds > 0 else 0.0
                elif attrs.get("expires") is not None:
                    try:
                        date = email.utils.parsedate_to_datetime(typing.cast(str, attrs["expires"]))
                        if date.tzinfo is None:
                            date = date.replace(tzinfo=datetime.timezone.utc)
                        expires = date.timestamp()
                    except (ValueError, TypeError, OverflowError, OSError):
                        pass
                self._put(name, value, domain, path, domain_attr is None, secure, expires)

    def set_cookie_header(self, request: Request) -> None:
        if "cookie" in request.headers:
            return
        self._expire()
        host = request.url.host.lower()
        path = request.url.path or "/"
        matches = []
        for (name, domain, cookie_path), (value, host_only, secure, _) in self._store.items():
            if domain and not (host == domain if host_only else self._domain_matches(host, domain)):
                continue
            if secure and request.url.scheme != "https":
                continue
            if not (path == cookie_path or (path.startswith(cookie_path) and (cookie_path.endswith("/") or path[len(cookie_path):].startswith("/")))):
                continue
            matches.append((cookie_path, name, value))
        matches.sort(key=lambda item: -len(item[0]))
        if matches:
            request.headers["cookie"] = "; ".join(f"{name}={value}" for _, name, value in matches)

    def set(self, name: str, value: str, domain: str = "", path: str = "/") -> None:
        self._put(name, value, domain.lower().lstrip("."), path, False, False, None)

    def get(self, name: str, default: str | None = None, domain: str | None = None, path: str | None = None) -> str | None:  # type: ignore
        self._expire()
        if domain is not None:
            domain = domain.lower().lstrip(".")
        values = [v[0] for (n, d, p), v in self._store.items() if n == name and (domain is None or d == domain) and (path is None or p == path)]
        if len(values) > 1:
            raise CookieConflict(f"Multiple cookies exist with name={name}")
        return values[0] if values else default

    def delete(self, name: str, domain: str | None = None, path: str | None = None) -> None:
        if domain is not None:
            domain = domain.lower().lstrip(".")
        for key in list(self._store):
            if key[0] == name and (domain is None or key[1] == domain) and (path is None or key[2] == path):
                del self._store[key]

    def clear(self, domain: str | None = None, path: str | None = None) -> None:
        if domain is not None:
            domain = domain.lower().lstrip(".")
        for key in list(self._store):
            if (domain is None or key[1] == domain) and (path is None or key[2] == path):
                del self._store[key]

    def update(self, cookies: CookieTypes | None = None) -> None:  # type: ignore
        if cookies is None or cookies is self:
            return
        if isinstance(cookies, CookieStore):
            cookies._expire()
            for (name, domain, path), (value, host_only, secure, expires) in list(cookies._store.items()):
                self._put(name, value, domain, path, host_only, secure, expires)
        elif isinstance(cookies, (Cookies, CookieJar)):
            jar = cookies.jar if isinstance(cookies, Cookies) else cookies
            for cookie in jar:
                self._put(cookie.name, cookie.value or "", cookie.domain.lower().lstrip("."), cookie.path or "/", bool(cookie.domain and not cookie.domain_specified), cookie.secure, cookie.expires)
        else:
            pairs = cookies.items() if isinstance(cookies, dict) else cookies
            for name, value in pairs:
                self.set(name, value)

    def __getitem__(self, name: str) -> str:
        value = self.get(name)
        if value is None:
            raise KeyError(name)
        return value

    def __setitem__(self, name: str, value: str) -> None:
        self.set(name, value)

    def __delitem__(self, name: str) -> None:
        if name not in self:
            raise KeyError(name)
        self.delete(name)

    def __iter__(self) -> typing.Iterator[str]:
        self._expire()
        return iter(dict.fromkeys(key[0] for key in self._store))

    def __len__(self) -> int:
        self._expire()
        return len(self._store)
